        }
    }
    object RequireMatePoseBudget(MatePlan plan,Dictionary<string,double[]> before,Dictionary<string,double[]> after,string stage) {
        var result=MatePosePolicy.Evaluate(before,after,plan.MaximumTranslationMm,plan.MaximumRotationDeg);result["stage"]=stage;
        if(!(bool)result["accepted"])throw new CadFault("MATE_POSE_CHANGE_EXCEEDS_CONFIRMED_BUDGET","配合导致组件位姿超出确认方案预算；拒绝提交并恢复检查点。若移动是设计意图，核对方向和参考后以明确预算重新预览，不重放旧方案。",result);
        return result;
    }
